import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useNavigate } from "react-router-dom";

const AdmListAluno = () => {
  const [alunos, setAlunos] = useState([]);
  const [filtro, setFiltro] = useState("");
  const navigate = useNavigate();

  // Buscar alunos no backend
  const fetchAlunos = async () => {
    try {
      const resposta = await fetch("http://localhost:5000/alunos");
      if (resposta.ok) {
        const dados = await resposta.json();
        setAlunos(dados);
      } else {
        console.error("Erro ao buscar alunos");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  useEffect(() => {
    fetchAlunos();
  }, []);

  // Filtrando alunos pelo nome
  const alunosFiltrados = alunos.filter((aluno) =>
    aluno.utilizador.nome.toLowerCase().includes(filtro.toLowerCase())
  );

  // Remover aluno
  const removerAluno = async (id) => {
    try {
      const resposta = await fetch(`http://localhost:5000/alunos/${id}`, {
        method: "DELETE",
      });

      if (resposta.ok) {
        fetchAlunos();
      } else {
        console.error("Erro ao remover aluno");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  // Alternar estado (ativo/inativo)
  const alternarEstado = async (id, estadoAtual) => {
    const novoEstado = estadoAtual === "A" ? "I" : "A";

    try {
      const resposta = await fetch(
        `http://localhost:5000/alunos/${id}/estado`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ estado: novoEstado }),
        }
      );

      if (resposta.ok) {
        fetchAlunos();
      } else {
        console.error("Erro ao atualizar estado");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <button
            className="nav-link"
            onClick={() => navigate("/admlistcurso")}
          >
            Cursos
          </button>
        </li>
        <li className="nav-item mx-2">
          <button className="nav-link" onClick={() => navigate("/admlistprof")}>
            Professores
          </button>
        </li>
        <li className="nav-item mx-2">
          <button
            className="nav-link active"
            onClick={() => navigate("/admlistaluno")}
          >
            Alunos
          </button>
        </li>
      </ul>

      <div className="d-flex justify-content-between align-items-center mt-3">
        <h3>Alunos</h3>
        <button
          className="btn btn-info"
          onClick={() => navigate("/admaddaluno")}
        >
          <i className="fas fa-plus"></i> Adicionar
        </button>
      </div>

      <div className="mt-3">
        <input
          type="text"
          className="form-control"
          placeholder="Filtrar alunos por nome"
          value={filtro}
          onChange={(e) => setFiltro(e.target.value)}
        />
      </div>

      <ul className="list-group mt-3">
        {alunosFiltrados.map((aluno) => (
          <li
            key={aluno.id}
            className="list-group-item d-flex justify-content-between align-items-center"
          >
            <div className="d-flex align-items-center">
              <span
                className={`badge me-2 ${
                  aluno.utilizador.estado === "A"
                    ? "bg-success"
                    : "bg-secondary"
                }`}
                style={{ cursor: "pointer" }}
                onClick={() =>
                  alternarEstado(aluno.id, aluno.utilizador.estado)
                }
                title="Clique para alterar o estado"
              >
                {aluno.utilizador.estado === "A" ? "Ativo" : "Inativo"}
              </span>

              <span
                className="text-primary"
                style={{ cursor: "pointer", textDecoration: "underline" }}
                onClick={() => navigate(`/adminfaluno/${aluno.id}`)}
              >
                {aluno.utilizador.nome}
              </span>
            </div>

            <div className="d-flex align-items-center">
              <button
                className="btn btn-outline-warning btn-sm mx-2"
                onClick={() => navigate(`/admeditaluno/${aluno.id}`)}
              >
                <i className="fas fa-pencil"></i> Editar
              </button>
              <button
                className="btn btn-outline-danger btn-sm"
                onClick={() => removerAluno(aluno.id)}
              >
                <i className="fas fa-trash"></i> Remover
              </button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default AdmListAluno;
